// science_service.oracle — frozen Python service-oracle replay (CONV-28).
//
// The fixture is generated by tools/oracle/generate_science_service_fixtures.py
// from the REAL Python production leaves (normalize_factor_samples /
// IDWInterpolator / _pure_numpy_kriging / generate_contour_layer /
// curve_operations / viz.geomodel.builders) plus explicitly-marked
// cpp-contract cases. Non-finite floats arrive as Python JSON literals
// (NaN / Infinity) and are parsed with pwb::mapping::parse_json_python_tolerant.
//
// Includes a comparator NEGATIVE SELF-CHECK: one expected value is corrupted
// in memory and the comparator must report the mismatch — a green replay
// then proves the comparisons can actually fail.

#include <cmath>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>

#include <pwb/domain/json.hpp>
#include <pwb/mapping/factor_grid_io.hpp>
#include <pwb/science_service/factor_service.hpp>
#include <pwb/science_service/geomodel_service.hpp>
#include <pwb/science_service/well_service.hpp>

#include <limits>

using namespace pwb::science_service;
using pwb::domain::Json;

namespace {

int g_failures = 0;

void check(bool ok, const std::string& what) {
    if (!ok) {
        std::fprintf(stderr, "FAIL %s\n", what.c_str());
        ++g_failures;
    }
}

bool close_to(double got, double want, double tol) {
    if (std::isnan(got) || std::isnan(want)) {
        return std::isnan(got) && std::isnan(want);
    }
    return std::fabs(got - want) <= tol + tol * std::fabs(want);
}

// null <-> NaN aware number compare (a non-finite double counts as null —
// Python serialized it as null and nlohmann keeps NaN as a number).
bool close_json(const Json& got, const Json& want, double tol) {
    const auto is_nullish = [](const Json& v) {
        return v.is_null()
               || (v.is_number() && !std::isfinite(v.get<double>()));
    };
    const bool got_null = is_nullish(got);
    const bool want_null = is_nullish(want);
    if (got_null || want_null) {
        return got_null && want_null;
    }
    if (!got.is_number() || !want.is_number()) {
        return got == want;
    }
    return close_to(got.get<double>(), want.get<double>(), tol);
}

bool compare_double_list(const std::vector<double>& got, const Json& want,
                         double tol, const std::string& what,
                         std::string& first_mismatch) {
    if (!want.is_array() || got.size() != want.size()) {
        first_mismatch = what + ": size mismatch";
        return false;
    }
    for (std::size_t i = 0; i < got.size(); ++i) {
        if (!close_json(Json(got[i]), want.at(i), tol)) {
            first_mismatch = what + "[" + std::to_string(i) + "]";
            return false;
        }
    }
    return true;
}

// Comparator states so the negative self-check can reuse the same logic.
struct CompareOutcome {
    bool ok = true;
    std::string mismatch;
    void fail(const std::string& m) {
        if (ok) {
            ok = false;
            mismatch = m;
        }
    }
};

void run_factor_case(const Json& cs, FactorInterpolationService& svc,
                     CompareOutcome& out) {
    FactorInterpolationRequest req;
    req.factor_name = cs.at("request").at("factor_name");
    req.well_records = cs.at("request").at("records");
    req.duplicate_policy = cs.at("request").value("duplicate_policy",
                                                  std::string("mean"));
    req.interpolate.method = cs.at("request").value("method",
                                                    std::string("idw"));
    req.interpolate.grid_n = cs.at("request").value("grid_n", 10);
    req.interpolate.power = cs.at("request").value("power", 2.0);
    req.crs = cs.at("request").value("crs", std::string());
    if (cs.at("request").contains("max_neighbors")) {
        req.interpolate.max_neighbors =
            cs.at("request").at("max_neighbors").get<int>();
    }
    if (cs.at("request").contains("search_radius")) {
        req.interpolate.search_radius =
            cs.at("request").at("search_radius").get<double>();
    }
    auto res = svc.run(req);
    if (!cs.at("ok").get<bool>()) {
        const Json& want = cs.at("error");
        if (!res.is_error()) {
            out.fail(cs.at("id").get<std::string>()
                     + ": expected error, got success");
            return;
        }
        if (res.error().diagnostics.empty()) {
            out.fail(cs.at("id").get<std::string>() + ": empty diagnostics");
            return;
        }
        if (res.error().diagnostics.at(0).code
            != want.at("code").get<std::string>()) {
            out.fail(cs.at("id").get<std::string>() + ": error code "
                     + res.error().diagnostics.at(0).code + " != "
                     + want.at("code").get<std::string>());
            return;
        }
        const std::string message = res.error().diagnostics.at(0).message;
        if (want.contains("message")
            && message != want.at("message").get<std::string>()) {
            out.fail(cs.at("id").get<std::string>() + ": error message '"
                     + message + "' != '" + want.at("message").get<std::string>()
                     + "'");
            return;
        }
        if (want.contains("message_contains")
            && message.find(want.at("message_contains").get<std::string>())
                   == std::string::npos) {
            out.fail(cs.at("id").get<std::string>()
                     + ": error message missing expected text");
            return;
        }
        return;
    }
    if (!res.has_value()) {
        out.fail(cs.at("id").get<std::string>() + ": expected success");
        return;
    }
    const auto& value = res.value();
    const std::string id = cs.at("id").get<std::string>();
    const bool kriging =
        cs.at("request").value("method", std::string("idw")) == "kriging";
    const double grid_tol = kriging ? 1e-4 : 1e-6;
    if (!compare_double_list(value.grid->grid_x, cs.at("grid_x"), 1e-9,
                             id + ".grid_x", out.mismatch)) {
        out.ok = false;
        return;
    }
    if (!compare_double_list(value.grid->grid_y, cs.at("grid_y"), 1e-9,
                             id + ".grid_y", out.mismatch)) {
        out.ok = false;
        return;
    }
    // grid_z row-major nested lists.
    const Json& want_rows = cs.at("grid_z");
    if (want_rows.size() != value.grid->grid_y.size()) {
        out.fail(id + ".grid_z rows");
        return;
    }
    for (std::size_t r = 0; r < want_rows.size(); ++r) {
        const Json& row = want_rows.at(r);
        if (row.size() != value.grid->grid_x.size()) {
            out.fail(id + ".grid_z row width");
            return;
        }
        for (std::size_t c = 0; c < row.size(); ++c) {
            const float got = value.grid->grid_z[r * row.size() + c];
            if (!close_json(Json(static_cast<double>(got)), row.at(c),
                            grid_tol)) {
                out.fail(id + ".grid_z[" + std::to_string(r) + "]["
                         + std::to_string(c) + "]");
                return;
            }
        }
    }
    // Statistics.
    const Json& want_stats = cs.at("stats");
    const Json got_stats = pwb::mapping::grid_statistics_to_json(
        value.grid->statistics);
    for (const char* key : {"min", "max", "mean", "std"}) {
        if (!close_json(got_stats.at(key), want_stats.at(key), 1e-9)) {
            out.fail(id + std::string(".stats.") + key);
            return;
        }
    }
    for (const char* key : {"valid_count", "total_count"}) {
        if (got_stats.at(key) != want_stats.at(key)) {
            out.fail(id + std::string(".stats.") + key);
            return;
        }
    }
    // Normalization report.
    const Json& want_norm = cs.at("normalization");
    const Json& got_norm = value.normalization_report;
    for (const char* key :
         {"policy", "n_input", "n_valid", "n_nonfinite_dropped",
          "n_duplicate_groups", "n_duplicates_merged"}) {
        if (got_norm.at(key) != want_norm.at(key)) {
            out.fail(id + std::string(".normalization.") + key);
            return;
        }
    }
    // Distance policy annotation (CRS cases).
    if (cs.contains("distance_policy")) {
        const std::string annotation = value.grid->distance_policy_annotation;
        const Json& want = cs.at("distance_policy");
        if (want.at("annotation").is_string()
            && annotation != want.at("annotation").get<std::string>()) {
            out.fail(id + ".distance_policy.annotation");
            return;
        }
        if (want.at("policy").is_string()) {
            const std::string policy_name = value.grid->distance_policy;
            if (!policy_name.empty()
                && policy_name != want.at("policy").get<std::string>()) {
                out.fail(id + ".distance_policy.policy");
                return;
            }
        }
    }
    // Contour product levels + feature count.
    if (cs.contains("contour") && value.contours.has_value()) {
        const Json& want = cs.at("contour");
        if (!compare_double_list(value.contours->levels, want.at("levels"),
                                 1e-9, id + ".contour.levels", out.mismatch)) {
            out.ok = false;
            return;
        }
        if (static_cast<std::size_t>(want.at("n_features").get<long long>())
            != value.contours->features.size()) {
            out.fail(id + ".contour.n_features");
            return;
        }
    }
}

void run_curve_case(const Json& cs, CurveOperationService& svc,
                    CompareOutcome& out) {
    const std::string id = cs.at("id").get<std::string>();
    CurveOperationRequest req;
    req.operation = cs.at("request").value("operation", std::string("resample"));
    if (cs.at("request").contains("step")) {
        req.params = Json{{"step", cs.at("request").at("step")}};
    }
    if (cs.at("request").contains("depth")) {
        for (const auto& v : cs.at("request").at("depth")) {
            req.depth.push_back(v.is_null()
                                    ? std::numeric_limits<double>::quiet_NaN()
                                    : v.get<double>());
        }
    }
    if (cs.at("request").contains("values")) {
        for (const auto& v : cs.at("request").at("values")) {
            req.values.push_back(v.is_null()
                                     ? std::numeric_limits<double>::quiet_NaN()
                                     : v.get<double>());
        }
    }
    auto res = svc.run(req);
    if (!cs.at("ok").get<bool>()) {
        if (!res.is_error()) {
            out.fail(id + ": expected error");
            return;
        }
        const Json& want = cs.at("error");
        if (res.error().diagnostics.at(0).code
                != want.at("code").get<std::string>()
            || res.error().diagnostics.at(0).message.find(
                   want.at("message_contains").get<std::string>())
                   == std::string::npos) {
            out.fail(id + ": error code/message mismatch");
        }
        return;
    }
    if (!res.has_value()) {
        out.fail(id + ": expected success");
        return;
    }
    if (!compare_double_list(res.value().depth, cs.at("out_depth"), 1e-12,
                             id + ".out_depth", out.mismatch)) {
        out.ok = false;
        return;
    }
    if (!compare_double_list(res.value().values, cs.at("out_values"), 1e-12,
                             id + ".out_values", out.mismatch)) {
        out.ok = false;
    }
}

void run_geomodel_case(const Json& cs, GeomodelBuildService& build_svc,
                       GeomodelSectionService& section_svc,
                       CompareOutcome& out) {
    const std::string id = cs.at("id").get<std::string>();
    const std::string kind = cs.at("kind").get<std::string>();
    if (kind == "geomodel_section") {
        GeomodelSectionRequest req;
        req.source = cs.at("request").at("source");
        req.plane = cs.at("request").at("plane");
        auto res = section_svc.run(req);
        if (!res.has_value()) {
            out.fail(id + ": expected success");
            return;
        }
        // Geometric contract: one connected chain on the plane, spanning
        // the grid's y extent at the flat z (interior chaining order is
        // kernel-internal and not part of the oracle).
        const Json& want = cs.at("section_contract");
        const auto& lines = res.value().polylines;
        if (lines.size()
                != static_cast<std::size_t>(
                    want.at("n_polylines").get<long long>())) {
            out.fail(id + ": polyline count");
            return;
        }
        for (const auto& line : lines) {
            if (line.empty()) {
                out.fail(id + ": empty polyline");
                return;
            }
            for (const auto& v : line) {
                if (!close_to(v[0], want.at("x").get<double>(), 1e-9)
                    || !close_to(v[2], want.at("z").get<double>(), 1e-9)) {
                    out.fail(id + ": vertex off the section plane");
                    return;
                }
            }
            if (!close_to(line.front()[1], want.at("y_start").get<double>(),
                          1e-9)
                || !close_to(line.back()[1], want.at("y_end").get<double>(),
                             1e-9)) {
                out.fail(id + ": chain endpoints do not span the grid");
                return;
            }
        }
        return;
    }
    GeomodelBuildRequest req;
    req.top = cs.at("request").at("top");
    req.base = cs.at("request").at("base");
    auto res = build_svc.run(req);
    if (!res.has_value()) {
        out.fail(id + ": expected success");
        return;
    }
    const Json& want_qc = cs.at("qc");
    const Json& got_qc = res.value().envelope.quality.at("shell");
    for (const char* key :
         {"column_count", "dropped_crossed", "dropped_nan_nodes",
          "negative_thickness_count"}) {
        if (got_qc.at(key) != want_qc.at(key)) {
            out.fail(id + std::string(".qc.") + key);
            return;
        }
    }
    for (const char* key : {"min_thickness", "max_thickness",
                            "mean_thickness"}) {
        if (!close_json(got_qc.at(key), want_qc.at(key), 1e-9)) {
            out.fail(id + std::string(".qc.") + key);
            return;
        }
    }
    if (got_qc.at("closed") != want_qc.at("closed")) {
        out.fail(id + ".qc.closed");
        return;
    }
    if (cs.contains("volume")) {
        if (!close_to(res.value().envelope.quality.at("volume").get<double>(),
                      cs.at("volume").at("value").get<double>(), 1e-6)) {
            out.fail(id + ".volume");
        }
    }
}

}  // namespace

int main() {
    std::ifstream stream(PWB_SCIENCE_SERVICE_FIXTURE, std::ios::binary);
    if (!stream.good()) {
        std::fprintf(stderr, "FAIL cannot open fixture\n");
        return 1;
    }
    std::ostringstream buffer;
    buffer << stream.rdbuf();
    const Json oracle = pwb::mapping::parse_json_python_tolerant(buffer.str());

    FactorInterpolationService factor_svc{"oracle"};
    CurveOperationService curve_svc{"oracle"};
    GeomodelBuildService build_svc{"oracle"};
    GeomodelSectionService section_svc{"oracle"};

    int ran = 0;
    CompareOutcome outcome;
    for (const auto& cs : oracle.at("cases")) {
        const std::string kind = cs.at("kind").get<std::string>();
        if (kind == "factor") {
            run_factor_case(cs, factor_svc, outcome);
        } else if (kind == "curve_resample") {
            run_curve_case(cs, curve_svc, outcome);
        } else {
            run_geomodel_case(cs, build_svc, section_svc, outcome);
        }
        ++ran;
        if (!outcome.ok) {
            break;
        }
    }
    check(ran == oracle.at("cases").size(),
          "all cases ran (got " + std::to_string(ran) + ")");
    check(outcome.ok, "oracle replay: " + outcome.mismatch);

    // ---- comparator negative self-check -----------------------------------
    // Corrupt one expected statistic in memory; the same comparison that
    // just passed MUST now report the mismatch.
    {
        bool caught = false;
        for (const auto& cs : oracle.at("cases")) {
            if (cs.at("id").get<std::string>() == "idw_basic") {
                Json corrupted = cs;
                corrupted["stats"]["mean"] = 12345.0;
                CompareOutcome probe;
                run_factor_case(corrupted, factor_svc, probe);
                caught = !probe.ok
                         && probe.mismatch.find("stats.mean")
                                != std::string::npos;
                break;
            }
        }
        check(caught,
              "negative self-check: corrupted expectation is caught");
    }

    if (g_failures != 0) {
        std::fprintf(stderr, "science_service.oracle: %d failure(s)\n",
                     g_failures);
        return 1;
    }
    std::printf("science_service.oracle OK (%d cases)\n", ran);
    return 0;
}
